"""Offline checks of generated bytes and encoded CPU CRC kernel; never runs DUT."""
import ast
import json
import struct
import zlib
from pathlib import Path
from prepare import HERE,frame,BASE

def sx(v,n):return (v&((1<<n)-1))-(1<<n if v&(1<<(n-1)) else 0)

def main():
    for p in HERE.glob('*.py'):ast.parse(p.read_text(encoding='utf-8'))
    ref=json.loads((HERE/'generated/reference.json').read_text())
    code={BASE+i*4:int(v,16) for i,v in enumerate((HERE/'generated/cpu.dat').read_text().splitlines())}
    regs=[0]*32;memory={};pc=BASE
    def step(pc,regs,mem):
        ins=code[pc];op=ins&127;rd=(ins>>7)&31;rs1=(ins>>15)&31;rs2=(ins>>20)&31;f=(ins>>12)&7
        nxt=pc+4;a=regs[rs1];b=regs[rs2];v=None
        if op==0x37:v=ins&0xfffff000
        elif op==0x13:
            imm=sx(ins>>20,12)
            if f==0:v=a+imm
            elif f==4:v=a^(imm&0xffffffff)
            elif f==7:v=a&(imm&0xffffffff)
            elif f==1:v=a<<((ins>>20)&31)
            elif f==5:v=a>>((ins>>20)&31)
            else:raise AssertionError(hex(ins))
        elif op==0x33:
            if f==0:v=a+b
            elif f==4:v=a^b
            else:raise AssertionError(hex(ins))
        elif op==0x23:
            address=(a+sx(((ins>>25)<<5)|((ins>>7)&31),12))&0xffffffff
            assert f==2;mem[address]=b
        elif op==3:
            assert f==2;v=mem[(a+sx(ins>>20,12))&0xffffffff]
        elif op==0x63:
            off=sx(((ins>>31)<<12)|(((ins>>7)&1)<<11)|(((ins>>25)&63)<<5)|(((ins>>8)&15)<<1),13)
            assert f in (0,1)
            if (a==b)==(f==0):nxt=pc+off
        else:raise AssertionError(hex(ins))
        if v is not None and rd:regs[rd]=v&0xffffffff
        regs[0]=0;return nxt
    for _ in range(2000):
        if pc==ref['labels']['config_wait']:break
        pc=step(pc,regs,memory)
    else:raise AssertionError('table initialization did not terminate')
    results=[]
    for pattern in (1,2):
        data=frame(pattern)
        assert data==(HERE/f'generated/frame{pattern}.bin').read_bytes()
        assert data==bytes(int(v,16) for v in (HERE/f'generated/frame{pattern}.hex').read_text().splitlines())
        assert zlib.crc32(data)==ref['crc32'][pattern-1]
        for n in (1,17,256):
            r=regs.copy();m=memory.copy()
            m.update({0x41000000+i*4:v[0] for i,v in enumerate(struct.iter_unpack('<I',data[:n*4]))})
            r[10]=0x41000000;r[11]=0xffffffff;r[12]=n
            pc=ref['labels'][f'crc_{pattern}']
            for _ in range(n*45+50):
                # Stop immediately before reading hardware CRC metadata.
                if code[pc]==0x02842283:break  # lw t0,40(s0)
                pc=step(pc,r,m)
            else:raise AssertionError('encoded CRC kernel failed to terminate')
            assert r[11]==zlib.crc32(data[:n*4]),(pattern,n,hex(r[11]))
            results.append([pattern,n,f'{r[11]:08x}'])
    result=dict(status='OFFLINE_GENERATOR_AND_ENCODED_CPU_CRC_CHECK_PASS_HDL_NOT_RUN',CRC_kernel_samples=results,
                full_frame_CRC=[f'{v:08x}' for v in ref['crc32']],CPU_instructions=941)
    print(json.dumps(result,indent=2))
    return result

if __name__=='__main__':main()
